------------------------------------------------------------
-- Connections
------------------------------------------------------------

local function bind(signal, fn)

	local c =
		signal:Connect(fn)

	table.insert(
		State.Connections,
		c
	)

	return c
end

local function bindTarget(signal, fn)

	local c =
		signal:Connect(fn)

	table.insert(
		State.TargetConnections,
		c
	)

	return c
end

local function disconnectList(list)

	for _, c
		in ipairs(list)
	do

		pcall(function()
			c:Disconnect()
		end)
	end

	table.clear(list)
end

------------------------------------------------------------
-- Generic helpers
------------------------------------------------------------

local function cleanId(value)

	return
		tostring(
			value or ""
		):match("(%d+)")
end

local function getId(track)

	local ok, id =
		pcall(function()

			return
				track.Animation.AnimationId
		end)

	if not ok then
		return nil
	end

	return cleanId(id)
end

local function safe(fn, fallback)

	local ok, result =
		pcall(fn)

	if ok then
		return result
	end

	return fallback
end

local function clampNumber(
	value,
	minimum,
	maximum,
	fallback
)

	value =
		tonumber(value)

	if not value then
		return fallback
	end

	return
		math.clamp(
			value,
			minimum,
			maximum
		)
end

local function jitter(
	value,
	amount
)

	if not amount
		or amount <= 0
	then
		return value
	end

	return
		value
		+
		(
			(math.random() * 2 - 1)
			* amount
		)
end

------------------------------------------------------------
-- Profile
------------------------------------------------------------

local function makeProfile(id, track)

	local profile = {

		id = id,

		name =
			tostring(
				track.Name
				or "Animation"
			),

		count = 0,

		length = 0,

		speedLast = 0,

		speedMin = math.huge,

		speedMax = 0,

		speedSum = 0,

		speedCount = 0,

		lifeSum = 0,

		lifeCount = 0,

		lifeMin = math.huge,

		lifeMax = 0,

		weightTargetLast = 0,

		weightTargetMax = 0,

		weightCurrentMax = 0,

		priorities = {},

		loopTrue = 0,

		loopFalse = 0,

		lastSeen = os.clock(),
	}

	State.Profiles[id] =
		profile

	return profile
end

local function avgSpeed(profile)

	if
		not profile
		or profile.speedCount == 0
	then
		return 0
	end

	return
		profile.speedSum
		/
		profile.speedCount
end

local function avgLife(profile)

	if
		not profile
		or profile.lifeCount == 0
	then
		return 0
	end

	return
		profile.lifeSum
		/
		profile.lifeCount
end

local function modePriority(profile)

	if not profile then
		return "Action"
	end

	local best =
		"Action"

	local bestCount =
		-1

	for name, count
		in pairs(
			profile.priorities
		)
	do

		if count > bestCount then

			best =
				name

			bestCount =
				count
		end
	end

	return best
end

local function profileLooped(profile)

	if not profile then
		return false
	end

	return
		profile.loopTrue
		>
		profile.loopFalse
end

------------------------------------------------------------
-- Burst rule
------------------------------------------------------------

local function getBurstRule(id)

	if not CONFIG.BurstRules[id] then

		local profile =
			State.Profiles[id]

		local observedSpeed =
			profile
			and avgSpeed(profile)
			or 1

		CONFIG.BurstRules[id] = {

			name =
				profile
				and profile.name
				or "Animation",

			enabled = false,

			fireSpeed =
				math.max(
					observedSpeed,
					1
				),

			fireWindow =
				0.050,

			visualReplay =
				false,

			visualDelay =
				0.075,

			visualSpeed =
				observedSpeed > 0
				and observedSpeed
				or 1,

			visualFade =
				0.015,
		}
	end

	return
		CONFIG.BurstRules[id]
end

--==============================================================
-- BURSTER ENGINE
--==============================================================

local function burstTrack(track)

	if State.OwnGhostTracks[track] then
		return
	end

	if not CONFIG.BursterMaster then
		return
	end

	local id =
		getId(track)

	if not id then
		return
	end

	local rule =
		CONFIG.BurstRules[id]

	if
		not rule
		or not rule.enabled
	then
		return
	end

	--------------------------------------------------------
	-- Every playback gets a generation token.
	--------------------------------------------------------

	local token =
		(State.BurstTokens[track] or 0)
		+ 1

	State.BurstTokens[track] =
		token

	local originalSpeed =
		tonumber(
			track.Speed
		)

	if
		not originalSpeed
		or originalSpeed <= 0
	then

		originalSpeed =
			rule.visualSpeed
			or 1
	end

	local originalWeight =
		safe(
			function()

				return
					track.WeightTarget
			end,
			1
		)

	if
		not originalWeight
		or originalWeight <= 0
	then
		originalWeight = 1
	end

	local fireSpeed =
		tonumber(
			rule.fireSpeed
		)
		or 1

	--------------------------------------------------------
	-- FAST PHASE
	--------------------------------------------------------

	pcall(function()

		track:
			AdjustSpeed(
				fireSpeed
			)
	end)

	--------------------------------------------------------
	-- Delayed visual mode:
	--
	-- Keep the fast track visually suppressed while it
	-- advances markers/state.
	--------------------------------------------------------

	if rule.visualReplay then

		pcall(function()

			track:
				AdjustWeight(
					0,
					0
				)
		end)

		task.spawn(function()

			local started =
				os.clock()

			------------------------------------------------
			-- Keep enforcing:
			--    fast speed
			--    zero visual contribution
			------------------------------------------------

			while
				not State.Destroyed
				and track.IsPlaying
				and
				State.BurstTokens[track]
					== token
				and
				(
					os.clock()
					- started
				)
				<
				rule.fireWindow
			do

				pcall(function()

					track:
						AdjustSpeed(
							fireSpeed
						)

					track:
						AdjustWeight(
							0,
							0
						)
				end)

				RunService.Heartbeat:
					Wait()
			end

			if
				State.Destroyed
				or
				State.BurstTokens[track]
					~= token
				or
				not track.IsPlaying
			then
				return
			end

			------------------------------------------------
			-- Pause + rewind.
			------------------------------------------------

			pcall(function()

				track:
					AdjustSpeed(0)

				track.TimePosition =
					0

				track:
					AdjustWeight(
						0,
						0
					)
			end)

			------------------------------------------------
			-- Delayed visual.
			------------------------------------------------

			task.wait(
				math.max(
					0,
					rule.visualDelay
				)
			)

			if
				State.Destroyed
				or
				State.BurstTokens[track]
					~= token
				or
				not track.IsPlaying
			then
				return
			end

			local visualSpeed =
				tonumber(
					rule.visualSpeed
				)
				or originalSpeed

			------------------------------------------------
			-- Play normal-looking visual AFTER fast phase.
			------------------------------------------------

			pcall(function()

				track.TimePosition =
					0

				track:
					AdjustSpeed(
						visualSpeed
					)

				track:
					AdjustWeight(
						originalWeight,
						math.max(
							0,
							rule.visualFade
						)
					)
			end)

			print(
				string.format(
					"[BURST] %s | FIRE %.2fx %.3fs | VIS %.2fx +%.3fs",
					rule.name
						or id,

					fireSpeed,

					rule.fireWindow,

					visualSpeed,

					rule.visualDelay
				)
			)
		end)

	else

		----------------------------------------------------
		-- Old/simple proven behavior.
		----------------------------------------------------

		task.spawn(function()

			RunService.Heartbeat:
				Wait()

			if
				State.Destroyed
				or not track.IsPlaying
				or
				State.BurstTokens[track]
					~= token
			then
				return
			end

			pcall(function()

				track:
					AdjustSpeed(
						fireSpeed
					)
			end)
		end)

		print(
			string.format(
				"[BURST] %s | %.2fx",
				rule.name
					or id,
				fireSpeed
			)
		)
	end
end

--==============================================================
-- PROFILER
--==============================================================

local function recordTrackStart(track)

	if not CONFIG.LoggingEnabled then
		return
	end

	--------------------------------------------------------
	-- Don't let our own Ghost test tracks contaminate the
	-- learned statistics.
	--------------------------------------------------------

	if
		State.TargetPlayer == LP
		and
		State.OwnGhostTracks[track]
	then
		return
	end

	local id =
		getId(track)

	if not id then
		return
	end

	local profile =
		State.Profiles[id]
		or
		makeProfile(
			id,
			track
		)

	profile.count += 1

	profile.name =
		tostring(
			track.Name
			or profile.name
		)

	profile.lastSeen =
		os.clock()

	local speed =
		tonumber(
			track.Speed
		)
		or 0

	profile.speedLast =
		speed

	profile.speedMin =
		math.min(
			profile.speedMin,
			speed
		)

	profile.speedMax =
		math.max(
			profile.speedMax,
			speed
		)

	profile.speedSum +=
		speed

	profile.speedCount +=
		1

	profile.length =
		tonumber(
			track.Length
		)
		or profile.length

	local priority =
		safe(
			function()

				return
					track.Priority.Name
			end,
			"?"
		)

	profile.priorities[priority] =
		(
			profile.priorities[priority]
			or 0
		)
		+ 1

	local looped =
		safe(
			function()

				return
					track.Looped
			end,
			false
		)

	if looped then
		profile.loopTrue += 1
	else
		profile.loopFalse += 1
	end

	local current =
		safe(
			function()

				return
					track.WeightCurrent
			end,
			0
		)

	local target =
		safe(
			function()

				return
					track.WeightTarget
			end,
			0
		)

	profile.weightCurrentMax =
		math.max(
			profile.weightCurrentMax,
			current
		)

	profile.weightTargetLast =
		target

	profile.weightTargetMax =
		math.max(
			profile.weightTargetMax,
			target
		)

	local token =
		(
			State.TrackTokens[track]
			or 0
		)
		+ 1

	State.TrackTokens[track] =
		token

	local started =
		os.clock()

	if UI.UpdateProfileRow then
		UI.UpdateProfileRow(id)
	end

	task.spawn(function()

		RunService.Heartbeat:
			Wait()

		if
			State.Destroyed
			or
			State.TrackTokens[track]
				~= token
		then
			return
		end

		local c =
			safe(
				function()

					return
						track.WeightCurrent
				end,
				0
			)

		local t =
			safe(
				function()

					return
						track.WeightTarget
				end,
				0
			)

		profile.weightCurrentMax =
			math.max(
				profile.weightCurrentMax,
				c
			)

		profile.weightTargetLast =
			t

		profile.weightTargetMax =
			math.max(
				profile.weightTargetMax,
				t
			)

		if UI.UpdateProfileRow then
			UI.UpdateProfileRow(id)
		end

		----------------------------------------------------
		-- Lifetime profiler
		----------------------------------------------------

		while
			not State.Destroyed
			and
			State.TrackTokens[track]
				== token
			and
			safe(
				function()

					return
						track.IsPlaying
				end,
				false
			)
		do

			task.wait(0.01)
		end

		if
			State.Destroyed
			or
			State.TrackTokens[track]
				~= token
		then
			return
		end

		local lifetime =
			os.clock()
			- started

		profile.lifeSum +=
			lifetime

		profile.lifeCount +=
			1

		profile.lifeMin =
			math.min(
				profile.lifeMin,
				lifetime
			)

		profile.lifeMax =
			math.max(
				profile.lifeMax,
				lifetime
			)

		if UI.UpdateProfileRow then
			UI.UpdateProfileRow(id)
		end

		if
			id
			== State.Selected
			and UI.RefreshGhost
		then

			UI.RefreshGhost()
		end
	end)
end

--==============================================================
-- GHOST ENGINE
--==============================================================

local GHOST_POSE_SIGNAL =
	safe(
		function()
			return RunService.PreSimulation
		end,
		nil
	)
	or RunService.Stepped

local function isLowerBodyMotor(motor)

	if not motor:IsA("Motor6D") then
		return false
	end

	local name =
		string.lower(
			motor.Name
		)

	if
		string.find(name, "hip", 1, true)
		or string.find(name, "knee", 1, true)
		or string.find(name, "ankle", 1, true)
	then
		return true
	end

	local part1Name =
		safe(
			function()
				return string.lower(motor.Part1.Name)
			end,
			""
		)

	return
		string.find(part1Name, "leg", 1, true)
		~= nil
		or
		string.find(part1Name, "foot", 1, true)
		~= nil
end

local function createGhostPoseGuard(track)

	if not CONFIG.Ghost.LegGuard then
		return nil
	end

	local character =
		LP.Character

	if not character then
		return nil
	end

	local guard = {
		snapshot = {},
		maxPosition = 0,
		maxRotation = 0,
		maxJoint = nil,
		signal = GHOST_POSE_SIGNAL,
	}

	for _, descendant
		in ipairs(
			character:GetDescendants()
		)
	do
		if isLowerBodyMotor(descendant) then

			local transform =
				safe(
					function()
						return descendant.Transform
					end,
					nil
				)

			if transform then
				guard.snapshot[descendant] =
					transform
			end
		end
	end

	if next(guard.snapshot) == nil then
		return nil
	end

	function guard:RestoreAndMeasure()

		for motor, baseline
			in pairs(self.snapshot)
		do
			pcall(function()

				local current =
					motor.Transform

				local delta =
					baseline:
						ToObjectSpace(current)

				local position =
					delta.Position.Magnitude

				local rx, ry, rz =
					delta:ToOrientation()

				local rotation =
					math.deg(
						math.max(
							math.abs(rx),
							math.abs(ry),
							math.abs(rz)
						)
					)

				if
					position > self.maxPosition
					or rotation > self.maxRotation
				then
					self.maxPosition =
						math.max(
							self.maxPosition,
							position
						)

					self.maxRotation =
						math.max(
							self.maxRotation,
							rotation
						)

					self.maxJoint =
						motor.Name
				end

				motor.Transform =
					baseline
			end)
		end
	end

	guard.connection =
		GHOST_POSE_SIGNAL:
			Connect(function()
				guard:RestoreAndMeasure()
			end)

	State.GhostPoseGuards[track] =
		guard

	return guard
end

local function releaseGhostPoseGuard(
	track,
	waitForStopFrame
)

	local guard =
		State.GhostPoseGuards[track]

	if not guard then
		return nil
	end

	if waitForStopFrame then
		guard.signal:Wait()
	end

	guard:RestoreAndMeasure()

	pcall(function()
		guard.connection:Disconnect()
	end)

	State.GhostPoseGuards[track] =
		nil

	return guard
end

local function stopGhostTrack(
	track,
	waitForStopFrame
)

	--------------------------------------------------------
	-- Drop the target before stopping. Keeping the pose
	-- guard through one simulation step catches a Stop(0)
	-- transition before it can reach a rendered frame.
	--------------------------------------------------------

	pcall(function()
		track:AdjustWeight(0, 0)
	end)

	pcall(function()
		track:Stop(0)
	end)

	return
		releaseGhostPoseGuard(
			track,
			waitForStopFrame
		)
end

local function stopAllGhosts()

	local tracks = {}

	for track
		in pairs(
			State.ActiveGhosts
		)
	do
		table.insert(
			tracks,
			track
		)
	end

	for _, track
		in ipairs(tracks)
	do

		stopGhostTrack(
			track,
			false
		)

		State.ActiveGhosts[track] =
			nil
	end
end

local function computeGhostParameters(id)

	local ghost =
		CONFIG.Ghost

	local profile =
		State.Profiles[id]

	local speed =
		ghost.Speed

	local lifetime =
		ghost.Lifetime

	local weight =
		ghost.TargetWeight

	local priority =
		ghost.Priority

	local looped =
		false

	if
		ghost.AutoProfile
		and profile
	then

		if profile.speedCount > 0 then

			speed =
				avgSpeed(profile)

			if speed <= 0 then
				speed =
					ghost.Speed
			end
		end

		local learnedLife =
			avgLife(profile)

		if learnedLife > 0 then

			lifetime =
				math.min(
					learnedLife,
					ghost.AutoLifeCap
				)
		end

		if
			profile.weightTargetLast
			and
			profile.weightTargetLast > 0
		then

			weight =
				profile.weightTargetLast
		end

		if ghost.UseLearnedPriority then

			priority =
				modePriority(profile)
		end

		if ghost.UseLearnedLooped then

			looped =
				profileLooped(profile)
		end
	end

	speed =
		math.max(
			0.01,
			jitter(
				speed,
				ghost.SpeedJitter
			)
		)

	weight =
		math.max(
			0.001,
			jitter(
				weight,
				ghost.WeightJitter
			)
		)

	lifetime =
		math.max(
			0.001,
			lifetime
		)

	--------------------------------------------------------
	-- Calculate absurdly slow fade so WeightCurrent barely
	-- rises during the track's tiny lifetime.
	--------------------------------------------------------

	local fade =
		(
			lifetime
			* weight
			/
			math.max(
				ghost.VisibleCap,
				0.000001
			)
		)
		*
		ghost.FadeSafety

	fade =
		math.clamp(
			math.max(
				fade,
				ghost.MinFade
			),
			0.1,
			ghost.MaxFade
		)

	return {
		speed = speed,
		lifetime = lifetime,
		weight = weight,
		fade = fade,
		priority = priority,
		looped = looped,
	}
end

local function ghostFire(id)

	id =
		cleanId(id)

	if
		not id
		or not State.LocalAnimator
	then
		return nil
	end

	--------------------------------------------------------
	-- HARD SERIAL
	--------------------------------------------------------

	stopAllGhosts()

	local params =
		computeGhostParameters(id)

	local anim =
		Instance.new("Animation")

	anim.Name =
		"GHOST_"
		.. id

	anim.AnimationId =
		"rbxassetid://"
		.. id

	local track

	local ok =
		pcall(function()

			track =
				State.LocalAnimator:
					LoadAnimation(anim)
		end)

	if
		not ok
		or not track
	then

		pcall(function()
			anim:Destroy()
		end)

		return nil
	end

	State.OwnGhostTracks[track] =
		true

	State.ActiveGhosts[track] =
		true

	track.Name =
		"GHOST_"
		.. id

	track.Priority =
		PRIORITIES[
			params.priority
		]
		or
		Enum.AnimationPriority.Core

	track.Looped =
		params.looped

	createGhostPoseGuard(
		track
	)

	local played, playError =
		pcall(function()
			track:
				Play(
					params.fade,
					params.weight,
					params.speed
				)
		end)

	if not played then

		warn(
			"[GHOST] play failed",
			playError
		)

		stopGhostTrack(
			track,
			false
		)

		State.ActiveGhosts[track] =
			nil

		State.OwnGhostTracks[track] =
			nil

		pcall(function()
			track:Destroy()
		end)

		pcall(function()
			anim:Destroy()
		end)

		return nil
	end

	task.spawn(function()

		local started =
			os.clock()

		local maximumWeight =
			0

		local guarded =
			false

		while
			not State.Destroyed
			and track.IsPlaying
			and
			(
				os.clock()
				- started
			)
			<
			params.lifetime
		do

			RunService.Heartbeat:
				Wait()

			local current =
				safe(
					function()

						return
							track.WeightCurrent
					end,
					0
				)

			maximumWeight =
				math.max(
					maximumWeight,
					current
				)

			------------------------------------------------
			-- Hard kill if blending rises unexpectedly.
			------------------------------------------------

			if
				current
				>
				CONFIG.Ghost.VisibleCap
				* 1.5
			then

				guarded =
					true

				break
			end
		end

		local current =
			safe(
				function()

					return
						track.WeightCurrent
				end,
				0
			)

		local target =
			safe(
				function()

					return
						track.WeightTarget
				end,
				0
			)

		local position =
			safe(
				function()

					return
						track.TimePosition
				end,
				0
			)

		local poseGuard =
			stopGhostTrack(
				track,
				true
			)

		State.ActiveGhosts[track] =
			nil

		State.LastGhostDiagnostic = {
			priority = params.priority,

			joint =
				poseGuard
				and poseGuard.maxJoint
				or "-",

			position =
				poseGuard
				and poseGuard.maxPosition
				or 0,

			rotation =
				poseGuard
				and poseGuard.maxRotation
				or 0,
		}

		if
			not State.Destroyed
			and UI.RefreshGhost
		then
			task.defer(
				UI.RefreshGhost
			)
		end

		print(
			string.format(
				"[GHOST] %s | S %.3f | LIFE %.4f | FADE %.0f | W %.7f>%.4f | MAX %.7f | POS %.4f | PRI %s%s%s",
				id,
				params.speed,
				params.lifetime,
				params.fade,
				current,
				target,
				maximumWeight,
				position,
				tostring(params.priority),
				guarded
					and " | VIS-GUARD"
					or "",

				poseGuard
					and
					string.format(
						" | LEG %s POS %.6f ROT %.3f",
						poseGuard.maxJoint
							or "-",
						poseGuard.maxPosition,
						poseGuard.maxRotation
					)
					or ""
			)
		)

		task.delay(
			0.10,
			function()

				State.OwnGhostTracks[track] =
					nil

				pcall(function()
					track:Destroy()
				end)

				pcall(function()
					anim:Destroy()
				end)
			end
		)
	end)

	return track, params
end

local function poolHas(id)

	for _, existing
		in ipairs(
			State.GhostPool
		)
	do

		if existing == id then
			return true
		end
	end

	return false
end

local function addGhostPool(id)

	id =
		cleanId(id)

	if
		id
		and not poolHas(id)
	then

		table.insert(
			State.GhostPool,
			id
		)
	end

	if UI.RefreshGhost then
		UI.RefreshGhost()
	end
end

local function stopGhostRunner()

	State.GhostRunning =
		false

	State.GhostToken +=
		1

	stopAllGhosts()

	if UI.RefreshGhost then
		UI.RefreshGhost()
	end
end

local function startGhostRunner()

	if State.GhostRunning then
		return
	end

	if
		#State.GhostPool == 0
	then

		addGhostPool(
			State.Selected
		)
	end

	if
		#State.GhostPool == 0
	then
		return
	end

	State.GhostRunning =
		true

	State.GhostToken +=
		1

	local token =
		State.GhostToken

	if UI.RefreshGhost then
		UI.RefreshGhost()
	end

	task.spawn(function()

		local index = 0

		while
			not State.Destroyed
			and State.GhostRunning
			and
			State.GhostToken
				== token
		do

			------------------------------------------------
			-- Explicitly guarantee previous track is dead
			-- BEFORE the next one exists.
			------------------------------------------------

			stopAllGhosts()

			task.wait(
				CONFIG.Ghost.Gap
			)

			local id

			if CONFIG.Ghost.RandomOrder then

				id =
					State.GhostPool[
						math.random(
							1,
							#State.GhostPool
						)
					]

			else

				index += 1

				if
					index
					>
					#State.GhostPool
				then
					index = 1
				end

				id =
					State.GhostPool[index]
			end

			local _, params =
				ghostFire(id)

			local waitTime =
				CONFIG.Ghost.Interval

			if params then

				waitTime =
					math.max(
						waitTime,
						params.lifetime
							+
						CONFIG.Ghost.Gap
					)
			end

			task.wait(
				waitTime
			)
		end
	end)
end

--==============================================================
-- WEBHOOK ENGINE
--==============================================================

local function webhookPost(payload)

	local url =
		CONFIG.Webhook.URL

	if
		not url
		or url == ""
	then

		warn(
			"[WEBHOOK] no URL set"
		)

		return false,
			"no URL set"
	end

	local rawRequest =
		getRequestImplementation()

	if not rawRequest then

		warn(
			"[WEBHOOK] no request implementation"
		)

		return false,
			"no request implementation"
	end

	local ok, result =
		pcall(
			rawRequest,
			{
				Url = url,

				Method = "POST",

				Headers = {
					["Content-Type"] =
						"application/json",
				},

				Body =
					HttpService:
						JSONEncode(
							payload
						),
			}
		)

	if not ok then

		warn(
			"[WEBHOOK]",
			result
		)

		return false,
			tostring(result)
	end

	if type(result) ~= "table" then

		warn(
			"[WEBHOOK] invalid response",
			type(result)
		)

		return false,
			"request returned "
				..
				type(result)
	end

	local status =
		tonumber(
			result.StatusCode
			or result.Status
			or result.status_code
		)

	if
		status
		and
		(
			status < 200
			or status >= 300
		)
	then

		warn(
			"[WEBHOOK] HTTP",
			status
		)

		local body =
			tostring(
				result.Body
				or result.body
				or ""
			)

		return false,
			"HTTP "
				..
				tostring(status)
				..
				(
					body ~= ""
					and
					(
						": "
						..
						string.sub(body, 1, 160)
					)
					or ""
				)
	end

	if
		not status
		and result.Success ~= true
	then

		warn(
			"[WEBHOOK] response had no status code"
		)

		return false,
			"response had no status code"
	end

	return true,
		nil,
		status
end

local function callLootMethod(
	methodName,
	...
)

	local loot =
		getLootAPI()

	if type(loot) ~= "table" then
		return false,
			"Loot API not found"
	end

	local method =
		loot[methodName]

	if type(method) ~= "function" then
		return false,
			"Loot."
				..
				methodName
				..
				" is not available"
	end

	local ok, result, detail =
		pcall(
			method,
			...
		)

	if not ok then
		return false,
			tostring(result)
	end

	--------------------------------------------------------
	-- pcall only reports whether Lua raised. Respect APIs
	-- that explicitly return false for a delivery failure.
	--------------------------------------------------------

	if result == false then
		return false,
			tostring(
				detail
				or "Loot API reported failure"
			)
	end

	return true,
		result
end

local function syncLootConfiguration()

	local options = {
		username = CONFIG.Webhook.Username,
		userID = CONFIG.Webhook.UserID,
	}

	-- Do not erase a URL that was configured directly in the pre-loader
	-- notifier merely because the GUI has no saved preference yet.
	if
		CONFIG.Webhook.URL
		and CONFIG.Webhook.URL ~= ""
	then
		options.url = CONFIG.Webhook.URL
	end

	return callLootMethod(
		"configure",
		options
	)
end

local function sendWebhookText(message)

	--------------------------------------------------------
	-- Prefer Loot because it captured its request function
	-- before Project Rain loaded. SET URL synchronizes Loot's
	-- private config through Loot.configure.
	--------------------------------------------------------

	local content =
		tostring(message or "")

	local userID =
		tostring(
			CONFIG.Webhook.UserID
			or ""
		):match("^%s*(%d+)%s*$")

	if userID then
		content =
			"<@"
			..
			userID
			..
			"> "
			..
			content
	end

	local lootSuccess, lootDetail =
		callLootMethod(
			"text",
			content
		)

	if lootSuccess then
		return true,
			"via Loot API"
	end

	--------------------------------------------------------
	-- Standalone fallback for use without the Loot module.
	--------------------------------------------------------

	if
		not CONFIG.Webhook.URL
		or CONFIG.Webhook.URL == ""
	then
		return false,
			"Loot API",
			lootDetail
	end

	local directSuccess, directDetail =
		webhookPost({
			username =
				CONFIG.Webhook.Username,

			content =
				content,
		})

	if directSuccess then
		return true,
			"direct fallback"
	end

	return false,
		"Loot/direct",
		tostring(lootDetail)
			..
			"; "
			..
			tostring(directDetail)
end

--==============================================================
-- LOCAL ANIMATOR
--==============================================================

local function hookLocalAnimator(animator)

	State.LocalAnimator =
		animator

	if State.LocalAnimatorConnection then

		pcall(function()

			State.LocalAnimatorConnection:
				Disconnect()
		end)
	end

	State.LocalAnimatorConnection =
		animator.AnimationPlayed:
			Connect(function(track)

				if State.Destroyed then
					return
				end

				burstTrack(track)
			end)

	table.insert(
		State.Connections,
		State.LocalAnimatorConnection
	)
end

local function hookLocalCharacter(character)

	local humanoid =
		character:
			WaitForChild(
				"Humanoid",
				10
			)

	if not humanoid then
		return
	end

	local animator =
		humanoid:
			FindFirstChildOfClass(
				"Animator"
			)
		or
		humanoid:
			WaitForChild(
				"Animator",
				10
			)

	if animator then

		hookLocalAnimator(
			animator
		)
	end
end

--==============================================================
-- TARGET INSPECTOR
--==============================================================

local function clearTargetConnections()

	disconnectList(
		State.TargetConnections
	)

	if State.TargetAnimatorConnection then

		pcall(function()

			State.TargetAnimatorConnection:
				Disconnect()
		end)

		State.TargetAnimatorConnection =
			nil
	end
end

local function clearProfiles()

	State.Profiles = {}

	if UI.ClearLogRows then
		UI.ClearLogRows()
	end
end

local function clearLiveRows()

	for _, row
		in pairs(
			State.LiveRows
		)
	do

		pcall(function()

			row.button:
				Destroy()
		end)
	end

	State.LiveRows =
		setmetatable(
			{},
			{ __mode = "k" }
		)

	State.LastSeen =
		setmetatable(
			{},
			{ __mode = "k" }
		)
end

local function hookTargetAnimator(animator)

	State.TargetAnimator =
		animator

	if State.TargetAnimatorConnection then

		pcall(function()

			State.TargetAnimatorConnection:
				Disconnect()
		end)
	end

	State.TargetAnimatorConnection =
		animator.AnimationPlayed:
			Connect(function(track)

				if State.Destroyed then
					return
				end

				pcall(
					recordTrackStart,
					track
				)
			end)

	table.insert(
		State.TargetConnections,
		State.TargetAnimatorConnection
	)
end

local function attachTargetCharacter(
	player,
	character
)

	task.spawn(function()

		local humanoid =
			character:
				WaitForChild(
					"Humanoid",
					10
				)

		if
			not humanoid
			or
			State.TargetPlayer
				~= player
		then
			return
		end

		local animator =
			humanoid:
				FindFirstChildOfClass(
					"Animator"
				)
			or
			humanoid:
				WaitForChild(
					"Animator",
					10
				)

		if
			animator
			and
			State.TargetPlayer
				== player
		then

			hookTargetAnimator(
				animator
			)
		end
	end)
end

local function setTarget(player)

	if not player then
		return
	end

	clearTargetConnections()

	clearProfiles()

	clearLiveRows()

	State.TargetPlayer =
		player

	State.TargetAnimator =
		nil

	if UI.SetTargetText then

		UI.SetTargetText(
			player
		)
	end

	if player.Character then

		attachTargetCharacter(
			player,
			player.Character
		)
	end

	bindTarget(
		player.CharacterAdded,
		function(character)

			if
				State.TargetPlayer
				== player
			then

				attachTargetCharacter(
					player,
					character
				)
			end
		end
	)
end

local function cycleTarget()

	local players =
		Players:GetPlayers()

	table.sort(
		players,
		function(a, b)

			if a == LP then
				return true
			end

			if b == LP then
				return false
			end

			return
				a.Name < b.Name
		end
	)

	local index = 1

	for i, p
		in ipairs(players)
	do

		if
			p
			== State.TargetPlayer
		then

			index = i
			break
		end
	end

	index += 1

	if index > #players then
		index = 1
	end

	setTarget(
		players[index]
	)
end

