local function openPage(target)

	for tab, page
		in pairs(Pages)
	do

		local active =
			page == target

		page.Visible =
			active

		tab.BackgroundColor3 =
			active
			and
			Color3.fromRGB(
				42,
				42,
				48
			)
			or
			COLORS.PANEL

		tab.TextColor3 =
			active
			and COLORS.TEXT
			or COLORS.MUTED
	end
end

