		row.text.Text =
			string.format(
				"%-13s x%-3d S:%4.2f[%4.2f-%4.2f] L:%4.2f LIFE:%5.3f WT:%5.3f WC:%6.4f %-7s",
				id,
				profile.count,
				avgSpeed(profile),

				profile.speedMin
					== math.huge
					and 0
					or
					profile.speedMin,

				profile.speedMax,

				profile.length,

				avgLife(profile),

				profile.weightTargetLast,

				profile.weightCurrentMax,

				modePriority(profile)
			)

		updateLogCanvas()
	end

