UI.RefreshGhost =
	function()

		local id =
			State.Selected

		GhostID.Text =
			"Selected: "
			..
			id

		local profile =
			State.Profiles[id]

		if profile then

			GhostProfileText.Text =
				string.format(
					"learned: S %.3f [%.3f-%.3f] | LIFE %.4f | WT %.4f | WCmax %.6f | %s",
					avgSpeed(profile),

					profile.speedMin
						== math.huge
						and 0
						or
						profile.speedMin,

					profile.speedMax,

					avgLife(profile),

					profile.weightTargetLast,

					profile.weightCurrentMax,

					modePriority(profile)
				)

		else

			GhostProfileText.Text =
				"no learned profile for selected animation"
		end

		local diagnostic =
			State.LastGhostDiagnostic

		if diagnostic then
			GhostProfileText.Text ..=
				string.format(
					"\nlast: %s | leg %s | pos %.6f | rot %.3f deg",
					diagnostic.priority
						or "?",
					diagnostic.joint,
					diagnostic.position,
					diagnostic.rotation
				)
		end

		AutoProfileButton.Text =
			CONFIG.Ghost.AutoProfile
			and "AUTO: ON"
			or "AUTO: OFF"

		AutoProfileButton.BackgroundColor3 =
			CONFIG.Ghost.AutoProfile
			and COLORS.GREEN
			or COLORS.RED

		GhostPriorityButton.Text =
			CONFIG.Ghost.UseLearnedPriority
			and "PRIORITY: LEARN"
			or
			"PRIORITY: "
				..
				CONFIG.Ghost.Priority

		GhostPriorityButton.BackgroundColor3 =
			CONFIG.Ghost.UseLearnedPriority
			and COLORS.RED
			or
			(
				CONFIG.Ghost.Priority == "Action"
				and COLORS.BLUE
				or COLORS.GREEN
			)

		RandomButton.Text =
			CONFIG.Ghost.RandomOrder
			and "ORDER:RANDOM"
			or "ORDER:SEQ"

		StartGhostButton.Text =
			State.GhostRunning
			and "RUNNING"
			or "START"

		LegGuardButton.Text =
			CONFIG.Ghost.LegGuard
			and "LEGS: GUARDED"
			or "LEGS: FREE"

		LegGuardButton.BackgroundColor3 =
