			)

		GhostInterval.Text =
			string.format(
				"%.4f",
				CONFIG.Ghost.Interval
			)

		GhostGap.Text =
			string.format(
				"%.4f",
				CONFIG.Ghost.Gap
			)

		GhostFadeMin.Text =
			string.format(
				"%.0f",
				CONFIG.Ghost.MinFade
			)

		GhostSafety.Text =
			string.format(
				"%.2f",
				CONFIG.Ghost.FadeSafety
			)

		GhostAutoLife.Text =
			string.format(
				"%.4f",
