local function refreshWebhook()

	local loot =
		getLootAPI()

	local hasLoot =
		loot ~= nil

	local lootStatus = nil

	if
		hasLoot
		and type(loot.getStatus) == "function"
	then
		local ok, result =
			pcall(loot.getStatus)

		if ok and type(result) == "table" then
			lootStatus = result
		end
	end

	local requestReady =
		getRequestImplementation()
		~= nil
		or
		(
			lootStatus
			and lootStatus.httpReady
		)

	local urlReady =
		CONFIG.Webhook.URL
		and
		CONFIG.Webhook.URL ~= ""

	LootStatus.Text =
		string.format(
			"Loot API: %s    HTTP: %s    Loot URL: %s",
			hasLoot
				and "DETECTED"
				or "NOT FOUND",

			requestReady
				and "READY"
				or "MISSING",

			(
				(
					lootStatus
					and lootStatus.configured
				)
				or urlReady
			)
				and "SET"
				or "NOT SET"
		)

	if urlReady then

		URLBox.Text =
			"[ webhook configured ]"

	else

		URLBox.Text =
			""
	end

	refreshStatus()
end

bind(
	URLBox.Focused,
	function()

		if
			URLBox.Text
			==
			"[ webhook configured ]"
		then

			URLBox.Text =
				""
		end
	end
)

bind(
	SetURL.MouseButton1Click,
	function()

		local candidate =
			URLBox.Text

		if
			candidate
			and
			candidate ~= ""
			and
			string.find(
				candidate,
				"/api/webhooks/",
				1,
				true
			)
		then

			CONFIG.Webhook.URL =
				candidate

			PREFS.WebhookURL =
				candidate

			URLBox.Text =
				"[ webhook configured ]"

			local synced, syncDetail =
				callLootMethod(
					"configure",
					{
						url = candidate,
					}
				)

			WebhookResult.Text =
				synced
				and "Webhook stored and synced to Loot."
				or
				(
					getLootAPI()
					and
					(
						"Direct URL stored; Loot sync failed: "
						..
						tostring(syncDetail)
					)
					or "Webhook stored for direct sends."
				)

		else

			WebhookResult.Text =
				"That does not look like a Discord webhook URL."
		end

		refreshWebhook()
	end
)

