--==============================================================
-- DESTROY
--==============================================================

function State:Destroy()

	if self.Destroyed then
		return
	end

	stopGhostRunner()

	stopAllGhosts()

	leaveUI()

	self.Destroyed =
		true

	CONFIG.BursterMaster =
		false

	CONFIG.LoggingEnabled =
		false

	clearTargetConnections()

	for _, c
		in ipairs(
			self.Connections
		)
	do

		pcall(function()

			c:
				Disconnect()
		end)
	end

	table.clear(
		self.Connections
	)

	for track
		in pairs(
			self.OwnGhostTracks
		)
	do

		pcall(function()

			track:
				Stop(0)
		end)

		pcall(function()

			track:
				Destroy()
		end)
	end

	pcall(function()

		Gui:
			Destroy()
	end)

	if
		ENV.__ANIM_LAB_V6
		==
		self
	then

		ENV.__ANIM_LAB_V6 =
			nil
	end

	print(
		"[ANIM] v6.2 unloaded"
	)
end

